create table okr_check_ins (
  id text not null,
  goal_id text not null,
  author_id text not null,
  week integer not null,
  posted_at timestamp with time zone not null default now(),
  value numeric,
  stages jsonb,
  status text not null,
  calculated text not null,
  cause text,
  why text not null default ''::text,
  greener_why text not null default ''::text,
  propose_target numeric,
  ptg_what text,
  ptg_by_week integer,
  ptg_needs text not null default ''::text,
  next text not null default ''::text,
  data_flagged boolean not null default false,
  workspace_id text not null default 'example'::text,
  ptg_state text,
  backfilled boolean not null default false,
  removed_at timestamp with time zone,
  removed_by text,
  reading jsonb,
  constraint okr_check_ins_pkey PRIMARY KEY (id),
  constraint okr_check_ins_author_id_fkey FOREIGN KEY (author_id) REFERENCES okr_people(id),
  constraint okr_check_ins_goal_id_fkey FOREIGN KEY (goal_id) REFERENCES okr_goals(id) ON DELETE CASCADE,
  constraint okr_check_ins_calculated_check CHECK ((calculated = ANY (ARRAY['on'::text, 'risk'::text, 'off'::text, 'done'::text]))),
  constraint okr_check_ins_cause_check CHECK ((cause = ANY (ARRAY['aggressive'::text, 'slower'::text, 'blocked'::text, 'external'::text, 'data'::text, 'cautious'::text, 'early'::text, 'oneoff'::text, 'other'::text]))),
  constraint okr_check_ins_check1 CHECK (((
CASE status
    WHEN 'off'::text THEN 3
    WHEN 'risk'::text THEN 2
    ELSE 1
END >=
CASE calculated
    WHEN 'off'::text THEN 3
    WHEN 'risk'::text THEN 2
    ELSE 1
END) OR (length(TRIM(BOTH FROM greener_why)) >= 10))),
  constraint okr_check_ins_ptg_state_check CHECK (((ptg_state IS NULL) OR (ptg_state = ANY (ARRAY['plan'::text, 'investigating'::text, 'help'::text, 'target'::text])))),
  constraint okr_check_ins_reading_ok CHECK (((reading IS NULL) OR ((jsonb_typeof(reading) = 'object'::text) AND (reading ? 'source'::text) AND (reading ? 'value'::text) AND (reading ? 'at'::text)))),
  constraint okr_check_ins_status_check CHECK ((status = ANY (ARRAY['on'::text, 'risk'::text, 'off'::text, 'done'::text]))),
  constraint okr_check_ins_way_back CHECK (((status <> ALL (ARRAY['risk'::text, 'off'::text])) OR ((length(TRIM(BOTH FROM COALESCE(ptg_what, ''::text))) >= 8) AND ((COALESCE(ptg_state, 'plan'::text) <> 'plan'::text) OR (COALESCE(ptg_by_week, 0) > week))))),
  constraint okr_check_ins_week_check CHECK ((week >= 1))
);

