  constraint okr_markups_strokes_check CHECK (((jsonb_typeof(strokes) = 'array'::text) AND (octet_length((strokes)::text) <= 200000))),
  constraint okr_markups_wont_fix_reason_check CHECK (((wont_fix_reason IS NULL) OR ((length(TRIM(BOTH FROM wont_fix_reason)) >= 1) AND (length(TRIM(BOTH FROM wont_fix_reason)) <= 2000)))),
