-- ---------- Functions ----------

-- 41 functions; 34 run with their owner's rights (security definer).

CREATE OR REPLACE FUNCTION faro.okr_builder_token_create(ws text, person text, token_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare
  nm text := trim(coalesce(token_name, ''));
  e text := lower(trim(coalesce(coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'email', '')));
  secret text;
begin
  if not okr_is_builder() then raise exception 'Only builders, signed in to the inbox, make a builder token.' using errcode = 'P0001'; end if;
  if not exists (select 1 from okr_people p where p.id = person and p.workspace_id = ws) then
    raise exception 'There’s no one with that ID in this workspace.' using errcode = 'P0001';
  end if;
  if length(nm) < 2 or length(nm) > 120 then raise exception 'Say what the token is for.' using errcode = 'P0001'; end if;
  secret := okr_token_secret();
  insert into okr_api_tokens (id, workspace_id, person_id, name, token_hash, created_by, created_at, builder_email)
    values ('tok_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16), ws, person, nm, encode(sha256(convert_to(secret, 'UTF8')), 'hex'),
      person, now(), e);
  return secret;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_builder_token_revoke(token_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare e text := lower(trim(coalesce(coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'email', '')));
begin
  if not okr_is_builder() then raise exception 'Only builders, signed in to the inbox, revoke builder tokens.' using errcode = 'P0001'; end if;
  update okr_api_tokens set revoked_at = now() where id = token_id and builder_email = e and revoked_at is null;
  return found;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_builder_tokens()
 RETURNS TABLE(id text, workspace_id text, workspace_name text, person_id text, person_name text, name text, created_at timestamp with time zone, last_used_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare e text := lower(trim(coalesce(coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'email', '')));
begin
  if not okr_is_builder() then raise exception 'Only builders, signed in to the inbox, list builder tokens.' using errcode = 'P0001'; end if;
  return query
    select t.id, t.workspace_id, coalesce(w.name, t.workspace_id), t.person_id, coalesce(p.name, t.person_id), t.name, t.created_at, t.last_used_at
      from okr_api_tokens t
      left join okr_workspaces w on w.id = t.workspace_id
      left join okr_people p on p.id = t.person_id and p.workspace_id = t.workspace_id
     where t.builder_email = e and t.revoked_at is null
     order by t.created_at desc;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  new.version := coalesce(old.version, 0) + 1;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_check_expectations(ws text, expect jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare e jsonb; current_version int; current_id text;
begin
  if expect is null then return; end if;
  for e in select * from jsonb_array_elements(coalesce(expect->'goals', '[]'::jsonb)) loop
    select version into current_version from okr_goals where id = e->>'id' and workspace_id = ws;
    if found and (e->'version' is null or jsonb_typeof(e->'version') = 'null' or current_version <> (e->>'version')::int) then
      raise exception 'stale: goal %', e->>'id' using errcode = 'P0001';
    end if;
  end loop;
  for e in select * from jsonb_array_elements(coalesce(expect->'reviews', '[]'::jsonb)) loop
    select version into current_version from okr_reviews where id = e->>'id' and workspace_id = ws;
    if found and (e->'version' is null or jsonb_typeof(e->'version') = 'null' or current_version <> (e->>'version')::int) then
      raise exception 'stale: review %', e->>'id' using errcode = 'P0001';
    end if;
  end loop;
  for e in select * from jsonb_array_elements(coalesce(expect->'check_ins', '[]'::jsonb)) loop
    select id into current_id from okr_check_ins where goal_id = e->>'goal_id' and week = (e->>'week')::int;
    if (found and (e->>'id') is distinct from current_id) or (not found and e->>'id' is not null) then
      raise exception 'stale: check-in % week %', e->>'goal_id', e->>'week' using errcode = 'P0001';
    end if;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_commit(ws text, payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from okr_workspaces where id = ws) then raise exception 'no workspace %', ws using errcode = 'P0001'; end if;
  perform okr_same_workspace(ws, payload);
  perform okr_check_expectations(ws, payload->'expect');
  perform okr_write(ws, payload);
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_create_workspace(w jsonb, payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  insert into okr_workspaces select * from jsonb_populate_record(null::okr_workspaces, w);
  perform okr_same_workspace(w->>'id', payload);
  perform okr_write(w->>'id', payload);
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_delete_workspace(ws text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  if ws = 'example' then raise exception 'The example can’t be deleted.' using errcode = 'P0001'; end if;
  update okr_teams set lead_id = null where workspace_id = ws;
  update okr_goals set parent_id = null where workspace_id = ws;
  delete from okr_goal_metrics where workspace_id = ws;
  delete from okr_metrics where workspace_id = ws;
  delete from okr_requests where workspace_id = ws;
  delete from okr_views where workspace_id = ws;
  delete from okr_api_tokens where workspace_id = ws;
  delete from okr_feedback where workspace_id = ws;
  delete from okr_retros where workspace_id = ws;
  delete from okr_watches where workspace_id = ws;
  delete from okr_decisions where workspace_id = ws;
  delete from okr_check_ins where workspace_id = ws;
  delete from okr_stages where workspace_id = ws;
  delete from okr_changes where workspace_id = ws;
  delete from okr_reviews where workspace_id = ws;
  delete from okr_goals where workspace_id = ws;
  delete from okr_cycles where workspace_id = ws;
  delete from okr_people where workspace_id = ws;
  delete from okr_teams where workspace_id = ws;
  delete from okr_telemetry_spans where workspace_id = ws;
  delete from okr_telemetry_logs where workspace_id = ws;
  delete from okr_telemetry_metrics where workspace_id = ws;
  delete from okr_telemetry_daily where workspace_id = ws;
  delete from okr_workspaces where id = ws;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_feedback_add(ws text, rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  if rows is null or jsonb_typeof(rows) <> 'array' or jsonb_array_length(rows) = 0 then return; end if;
  if exists (select 1 from jsonb_array_elements(rows) r where (r->>'workspace_id') is distinct from ws) then
    raise exception 'a feedback row belongs to another workspace' using errcode = 'P0001';
  end if;
  perform okr_upsert('okr_feedback',
    (select jsonb_agg(r - 'status' - 'fixed_in' - 'wont_fix_reason' - 'status_by' - 'status_at') from jsonb_array_elements(rows) r),
    'id', 'nothing');
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_feedback_for_token(hash text, ws text DEFAULT NULL::text, st text DEFAULT NULL::text, fid text DEFAULT NULL::text, lim integer DEFAULT 50)
 RETURNS TABLE(id text, workspace_id text, workspace_name text, person_id text, person_name text, path text, mood text, text text, at timestamp with time zone, status text, fixed_in text, wont_fix_reason text, status_by text, status_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
begin
  if not okr_token_live(hash) then raise exception 'That token isn’t valid or has been revoked.' using errcode = 'P0001'; end if;
  return query select f.id, f.workspace_id, coalesce(w.name, ''), f.person_id, coalesce(p.name, ''), f.path, f.mood, f.text,
         f.at, f.status, f.fixed_in, f.wont_fix_reason, f.status_by, f.status_at
    from okr_feedback f
    left join okr_workspaces w on w.id = f.workspace_id
    left join okr_people p on p.workspace_id = f.workspace_id and p.id = f.person_id
   where (ws is null or f.workspace_id = ws) and (st is null or f.status = st) and (fid is null or f.id = fid)
   order by f.at desc, f.id desc
   limit least(greatest(coalesce(lim, 50), 1), 500);
end $function$;

