CREATE OR REPLACE FUNCTION faro.okr_token_live(hash text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
  select exists (select 1 from okr_api_tokens t where t.token_hash = hash and t.revoked_at is null)
$function$;

CREATE OR REPLACE FUNCTION faro.okr_token_revoke(ws text, token_id text, by_id text, change jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare t okr_api_tokens;
begin
  select * into t from okr_api_tokens where id = token_id and workspace_id = ws;
  if not found then raise exception 'There’s no token with that ID.' using errcode = 'P0001'; end if;
  if t.revoked_at is not null then return false; end if;
  if t.person_id <> by_id and not exists (select 1 from okr_people p where p.id = by_id and p.workspace_id = ws and p.is_admin) then
    raise exception 'Only an admin or the token’s person can revoke it.' using errcode = 'P0001';
  end if;
  if change is not null and (change->>'workspace_id') is distinct from ws then
    raise exception 'The change belongs to another workspace.' using errcode = 'P0001';
  end if;
  update okr_api_tokens set revoked_at = now() where id = token_id;
  if change is not null then perform okr_upsert('okr_changes', jsonb_build_array(change), 'id', 'nothing'); end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_token_secret()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare
  abc constant text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  secret text := 'gk_';
  raw bytea;
  n int := 0;
  i int;
begin
  while n < 40 loop
    raw := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    for i in 0..15 loop
      continue when i in (6, 8) or n >= 40;
      secret := secret || substr(abc, get_byte(raw, i) % 62 + 1, 1);
      n := n + 1;
    end loop;
  end loop;
  return secret;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_token_touch(hash text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'faro', 'pg_temp'
AS $function$
  update okr_api_tokens set last_used_at = now() where token_hash = hash and revoked_at is null
$function$;

CREATE OR REPLACE FUNCTION faro.okr_upsert(tbl regclass, rows jsonb, conflict text, mode text DEFAULT 'update'::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare cols text; upd text;
begin
  if rows is null or jsonb_typeof(rows) <> 'array' or jsonb_array_length(rows) = 0 then return; end if;
  select string_agg(quote_ident(a.attname), ', ' order by a.attnum),
         string_agg(format('%1$I = excluded.%1$I', a.attname), ', ' order by a.attnum)
    into cols, upd
    from pg_attribute a
   where a.attrelid = tbl and a.attnum > 0 and not a.attisdropped and a.attname <> 'version'
     and exists (select 1 from jsonb_array_elements(rows) r where r ? a.attname);
  if mode = 'nothing' then
    execute format('insert into %s (%s) select %s from jsonb_populate_recordset(null::%s, $1) on conflict (%s) do nothing', tbl, cols, cols, tbl, conflict) using rows;
  else
    execute format('insert into %s (%s) select %s from jsonb_populate_recordset(null::%s, $1) on conflict (%s) do update set %s', tbl, cols, cols, tbl, conflict, upd) using rows;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION faro.okr_write(ws text, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'faro', 'pg_temp'
AS $function$
declare s jsonb; m record;
  mods jsonb;
begin
  -- A module's rows, by table: none when `modules` is missing or null; anything else but an object stops the save.
  mods := case jsonb_typeof(p->'modules') when 'object' then p->'modules' when 'null' then '{}'::jsonb else null end;
  if mods is null and p ? 'modules' then raise exception 'a save''s modules must be an object of tables' using errcode = 'P0001'; end if;
  mods := coalesce(mods, '{}'::jsonb);
  -- Saves from before 0039 sent the metric library's rows under these two keys: read as its two tables. A save naming
  -- a table both ways stops, rather than keeping one and dropping the other without a word.
  if jsonb_typeof(p->'metrics') = 'array' then
    if mods ? 'okr_metrics' then raise exception 'a save names okr_metrics twice (as modules.okr_metrics and as metrics)' using errcode = 'P0001'; end if;
    mods := mods || jsonb_build_object('okr_metrics', p->'metrics');
  end if;
  if jsonb_typeof(p->'goal_metrics') = 'array' then
    if mods ? 'okr_goal_metrics' then raise exception 'a save names okr_goal_metrics twice (as modules.okr_goal_metrics and as goal_metrics)' using errcode = 'P0001'; end if;
    mods := mods || jsonb_build_object('okr_goal_metrics', p->'goal_metrics');
  end if;
  perform okr_upsert('okr_teams', p->'teams', 'id');
  perform okr_upsert('okr_people', p->'people', 'id');
  perform okr_upsert('okr_cycles', p->'cycles', 'id');
  perform okr_upsert('okr_goals', p->'goals', 'id');
  for s in select * from jsonb_array_elements(coalesce(p->'stages', '[]'::jsonb)) loop
    delete from okr_stages where workspace_id = ws and goal_id = s->>'goal_id'
      and not (id = any (array(select jsonb_array_elements_text(coalesce(s->'keep', '[]'::jsonb)))));
    perform okr_upsert('okr_stages', s->'rows', 'goal_id, id');
  end loop;
  perform okr_upsert('okr_check_ins', p->'check_ins', 'id');
  perform okr_upsert('okr_reviews', p->'reviews', 'id');
  if to_regprocedure('okr_feedback_add(text, jsonb)') is not null then
    execute 'select okr_feedback_add($1, $2)' using ws, p->'feedback';
  else
    perform okr_upsert('okr_feedback', p->'feedback', 'id', 'nothing');
  end if;
  perform okr_upsert('okr_retros', p->'retros', 'id');
  perform okr_upsert('okr_decisions', p->'decisions', 'id');
  perform okr_upsert('okr_watches', p->'watches', 'id');
  -- Saves from before 0025 removed a watch's row; the app now sets removed_at instead, and this stays for older clients.
  delete from okr_watches where workspace_id = ws and id = any (array(select jsonb_array_elements_text(coalesce(p->'unwatch', '[]'::jsonb))));
  perform okr_upsert('okr_views', p->'views', 'id');
  perform okr_upsert('okr_requests', p->'requests', 'id');
  -- Every module's rows, table by table in the allowed list's order (okr_same_workspace has refused any other table).
  for m in select t.table_name from module_tables t where mods ? t.table_name order by t.position, t.table_name loop
    perform okr_upsert(m.table_name::regclass, mods->m.table_name, 'id');
  end loop;
  -- A removed team's people and goals have moved above; a goal still on it stops the whole save.
  delete from okr_teams where workspace_id = ws and id = any (array(select jsonb_array_elements_text(coalesce(p->'remove_teams', '[]'::jsonb))));
  if coalesce(trim(p->>'workspace_name'), '') <> '' then
    update okr_workspaces set name = trim(p->>'workspace_name') where id = ws;
  end if;
  if jsonb_typeof(p->'workspace_recording') = 'boolean' then
    update okr_workspaces set recording = (p->>'workspace_recording')::boolean where id = ws;
  end if;
  if jsonb_typeof(p->'workspace_modules_off') = 'array' then
    update okr_workspaces set modules_off = array(select jsonb_array_elements_text(p->'workspace_modules_off')) where id = ws;
  end if;
  perform okr_upsert('okr_changes', p->'changes', 'id', 'nothing');
end $function$;

-- ---------- Triggers ----------

CREATE TRIGGER okr_goals_key BEFORE INSERT OR UPDATE OF key ON faro.okr_goals FOR EACH ROW EXECUTE FUNCTION okr_goal_key();
CREATE TRIGGER okr_goals_version BEFORE UPDATE ON faro.okr_goals FOR EACH ROW EXECUTE FUNCTION okr_bump_version();
CREATE TRIGGER okr_reviews_version BEFORE UPDATE ON faro.okr_reviews FOR EACH ROW EXECUTE FUNCTION okr_bump_version();
CREATE TRIGGER okr_workspaces_goal_keys AFTER DELETE ON faro.okr_workspaces FOR EACH ROW EXECUTE FUNCTION okr_goal_keys_forget();

